function build_tree(n) {
  let last_leaf = root;
  for (let i = 0; i < n; ++i) {
    const div = document.createElement('div');
    const inline_box = document.createElement('span');
    div.appendChild(inline_box);
    last_leaf.appendChild(div);
    last_leaf = inline_box;
  }
}
build_tree(30);

function run_test() {
  root.scrollIntoView();
}
